+      continue;
+    }
+    picked.push(r);
+    if (top !== undefined) usedTops.add(top);
+    if (bottom !== undefined) usedBottoms.add(bottom);
+  }
+
+  for (const r of rest) {
+    if (picked.length >= n) break;
+    picked.push(r);
+  }
+  return picked;
+}


